class Solution {
public:
    int minimumDistance(vector<vector<int>>& points) {
        int n = points.size();
        vector<long long> u(n), v(n);
        for (int i = 0; i < n; i++) { u[i] = points[i][0] + points[i][1]; v[i] = points[i][0] - points[i][1]; }
        auto top2 = [](vector<long long>& a) {
            long long mx1 = LLONG_MIN, mx2 = LLONG_MIN, mn1 = LLONG_MAX, mn2 = LLONG_MAX;
            for (long long x : a) {
                if (x > mx1) { mx2 = mx1; mx1 = x; } else if (x > mx2) mx2 = x;
                if (x < mn1) { mn2 = mn1; mn1 = x; } else if (x < mn2) mn2 = x;
            }
            return make_tuple(mx1, mx2, mn1, mn2);
        };
        auto [M1, M2, m1, m2] = top2(u);
        auto [N1, N2, p1, p2] = top2(v);
        long long ans = LLONG_MAX;
        for (int i = 0; i < n; i++) {
            long long mu = u[i] == M1 ? M2 : M1;
            long long nu = u[i] == m1 ? m2 : m1;
            long long mv = v[i] == N1 ? N2 : N1;
            long long nv = v[i] == p1 ? p2 : p1;
            ans = min(ans, max(mu - nu, mv - nv));
        }
        return (int) ans;
    }
};

