class Solution {
    public int minimumDistance(int[][] points) {
        int n = points.length;
        long[] u = new long[n], v = new long[n];
        for (int i = 0; i < n; i++) { u[i] = points[i][0] + points[i][1]; v[i] = points[i][0] - points[i][1]; }
        long M1 = Long.MIN_VALUE, M2 = Long.MIN_VALUE, m1 = Long.MAX_VALUE, m2 = Long.MAX_VALUE;
        long N1 = Long.MIN_VALUE, N2 = Long.MIN_VALUE, p1 = Long.MAX_VALUE, p2 = Long.MAX_VALUE;
        for (int i = 0; i < n; i++) {
            if (u[i] > M1) { M2 = M1; M1 = u[i]; } else if (u[i] > M2) M2 = u[i];
            if (u[i] < m1) { m2 = m1; m1 = u[i]; } else if (u[i] < m2) m2 = u[i];
            if (v[i] > N1) { N2 = N1; N1 = v[i]; } else if (v[i] > N2) N2 = v[i];
            if (v[i] < p1) { p2 = p1; p1 = v[i]; } else if (v[i] < p2) p2 = v[i];
        }
        long ans = Long.MAX_VALUE;
        for (int i = 0; i < n; i++) {
            long mu = u[i] == M1 ? M2 : M1, nu = u[i] == m1 ? m2 : m1;
            long mv = v[i] == N1 ? N2 : N1, nv = v[i] == p1 ? p2 : p1;
            ans = Math.min(ans, Math.max(mu - nu, mv - nv));
        }
        return (int) ans;
    }
}

