var minimumDistance = function(points) {
    const n = points.length;
    const u = points.map(p => p[0] + p[1]);
    const v = points.map(p => p[0] - p[1]);
    const top2 = (a) => {
        let mx1 = -Infinity, mx2 = -Infinity, mn1 = Infinity, mn2 = Infinity;
        for (const x of a) {
            if (x > mx1) { mx2 = mx1; mx1 = x; } else if (x > mx2) mx2 = x;
            if (x < mn1) { mn2 = mn1; mn1 = x; } else if (x < mn2) mn2 = x;
        }
        return [mx1, mx2, mn1, mn2];
    };
    const [M1, M2, m1, m2] = top2(u);
    const [N1, N2, p1, p2] = top2(v);
    let ans = Infinity;
    for (let i = 0; i < n; i++) {
        const mu = u[i] === M1 ? M2 : M1, nu = u[i] === m1 ? m2 : m1;
        const mv = v[i] === N1 ? N2 : N1, nv = v[i] === p1 ? p2 : p1;
        ans = Math.min(ans, Math.max(mu - nu, mv - nv));
    }
    return ans;
};
